keyboardTabs(document.querySelector('.workspace-tabs'),'[role=tab]',b=>setStage(b.id==='tab-content'?state.lastCategory:'map'));keyboardTabs($('content-tabs'),'[data-stage]',b=>setStage(b.dataset.stage));keyboardTabs($('placement-tabs'),'[data-placement]',b=>setPlacement(b.dataset.placement));
